// RETURN hook for Game::spinning_matrix: applies camera roll around Z axis.
fn on_return(value: glam::Mat4) -> glam::Mat4 {
    let roll = crate::game::barrel_roll::get_roll();
    if roll.abs() > 0.0001 {
        value * glam::Mat4::from_rotation_z(roll.to_radians())
    } else {
        value
    }
}

// Frame hook: advance the camera roll while active.
fn on_frame(game: &mut crate::game::Game<'_>, elapsed: std::time::Duration) {
    let _ = game;
    let _ = crate::game::barrel_roll::tick(elapsed);
}

// Key hook: 'B' toggles the barrel roll on/off.
fn on_key(game: &mut crate::game::Game<'_>, key: &str, pressed: bool) {
    let _ = game;
    if key == "key.b" && pressed {
        let active = !crate::game::barrel_roll::ACTIVE.load(std::sync::atomic::Ordering::Relaxed);
        crate::game::barrel_roll::set_active(active);
    }
}

