// Barrel-roll runtime: spins the camera when activated.
// This file is both the standalone Cargo library and the injected module.

use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::time::Duration;

/// Whether the barrel roll is currently active.
pub(crate) static ACTIVE: AtomicBool = AtomicBool::new(false);
/// Yaw offset applied during the roll, in degrees (bitcast as u32 for Sync).
pub(crate) static YAW_OFFSET: AtomicU32 = AtomicU32::new(0);

/// Toggle the roll on/off. Call from the key hook.
pub fn set_active(active: bool) {
    ACTIVE.store(active, Ordering::Relaxed);
    if !active {
        YAW_OFFSET.store(0, Ordering::Relaxed);
    }
}

pub fn get_roll() -> f32 {
    f32::from_bits(YAW_OFFSET.load(Ordering::Relaxed))
}

/// Advance the roll by `elapsed` seconds. Returns the yaw offset to apply.
pub fn tick(elapsed: Duration) -> f32 {
    let delta = elapsed.as_secs_f32();
    if ACTIVE.load(Ordering::Relaxed) {
        let mut offset = f32::from_bits(YAW_OFFSET.load(Ordering::Relaxed));
        // Spin ~720 degrees per second (two full barrel rolls per second)
        offset += delta * 720.0;
        if offset >= 360.0 {
            offset -= 360.0;
        }
        YAW_OFFSET.store(offset.to_bits(), Ordering::Relaxed);
        offset
    } else {
        0.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roll_spins_when_active() {
        set_active(true);
        let offset = tick(Duration::from_secs_f32(0.5));
        assert!((offset - 360.0).abs() < 0.01, "expected 360 deg after 0.5s, got {offset}");
        set_active(false);
        let offset = tick(Duration::from_secs_f32(1.0));
        assert_eq!(offset, 0.0, "inactive roll should not accumulate");
    }
}
